SELECT cd.cd_gender, cd.cd_marital_status, SUM(s.ss_net_paid) AS total_sales, SUM(cr.cr_return_amount) AS total_return_amount FROM store_sales s JOIN customer_demographics cd ON s.ss_cdemo_sk = cd.cd_demo_sk JOIN catalog_returns cr ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk WHERE cd.cd_gender = 'M' AND s.ss_sold_date_sk >= 2452252 AND s.ss_sold_date_sk <= 2452196 GROUP BY cd.cd_gender, cd.cd_marital_status
